// Fake Web Serial port for testing the UI without hardware (see README.md).
// Needs `window.MOCK` from mock-data.js (generated by mockgen) loaded first.
//
// Replaces `navigator.serial` so `requestPort()` returns a fake port that:
// - on open, delivers MOCK.backlog (split mid-frame across two reads), then
//   streams MOCK.live in real time (50 frames every 100 ms);
// - answers requests: decodes the COBS frame, reads the postcard-rpc header
//   (discriminant byte, key, sequence number) and replies with the reply key and
//   body from MOCK.endpoints and the request's sequence number (unknown keys:
//   MOCK.unknownKey, an error reply).
// To simulate other firmware, edit MOCK.endpoints before connecting.
// Test state is in `window.FAKE_SERIAL`.
(() => {
  const state = (window.FAKE_SERIAL = {
    requests: [], // paths of the requests received, in order ("?<key>" if unknown)
    opens: 0,
    closes: 0,
    liveSent: 0, // live frames delivered so far
  });

  const fromHex = (s) => Uint8Array.from(s.match(/../g) || [], (h) => parseInt(h, 16));
  const toHex = (a) => Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
  const concat = (parts) => {
    const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
    let i = 0;
    for (const p of parts) {
      out.set(p, i);
      i += p.length;
    }
    return out;
  };

  // COBS: replaces zeros so 0 can terminate frames. Each block starts with a code
  // byte = 1 + number of following non-zero bytes; a block shorter than 254 data
  // bytes implies a zero after it (except at the end of the frame).
  function cobsEncode(data) {
    const out = [0];
    let codeAt = 0;
    let code = 1;
    for (const b of data) {
      if (b === 0) {
        out[codeAt] = code;
        codeAt = out.length;
        out.push(0);
        code = 1;
      } else {
        out.push(b);
        code++;
        if (code === 0xff) {
          out[codeAt] = code;
          codeAt = out.length;
          out.push(0);
          code = 1;
        }
      }
    }
    out[codeAt] = code;
    return out;
  }

  function cobsDecode(frame) {
    const out = [];
    let i = 0;
    while (i < frame.length) {
      const code = frame[i++];
      for (let j = 1; j < code; j++) out.push(frame[i++]);
      if (code < 0xff && i < frame.length) out.push(0);
    }
    return out;
  }

  class FakePort {
    async open(_options) {
      if (this.isOpen) throw new DOMException("already open", "InvalidStateError");
      this.isOpen = true;
      state.opens++;
      this.rx = [];
      this.readable = new ReadableStream({
        start: (controller) => (this.controller = controller),
        cancel: () => this.stop(),
      });
      this.writable = new WritableStream({ write: (chunk) => this.onWrite(chunk) });

      const backlog = concat(MOCK.backlog.map(fromHex));
      const cut = Math.floor(backlog.length / 2) | 1;
      this.deliver(backlog.subarray(0, cut));
      this.deliver(backlog.subarray(cut));

      let next = 0;
      this.timer = setInterval(() => {
        if (next >= MOCK.live.length) return this.stop();
        const batch = MOCK.live.slice(next, next + 50);
        next += batch.length;
        state.liveSent = next;
        this.deliver(concat(batch.map(fromHex)));
      }, 100);
    }

    async close() {
      this.stop();
      this.isOpen = false;
      state.closes++;
    }

    stop() {
      clearInterval(this.timer);
    }

    deliver(bytes) {
      try {
        this.controller.enqueue(new Uint8Array(bytes));
      } catch (_) {
        // Stream already cancelled (disconnected).
      }
    }

    onWrite(chunk) {
      for (const b of chunk) {
        if (b !== 0) {
          this.rx.push(b);
          continue;
        }
        const request = cobsDecode(this.rx);
        this.rx = [];
        this.answer(request);
      }
    }

    answer(request) {
      const disc = request[0];
      const keyLen = 1 << (disc >> 6);
      const seqLen = 1 << ((disc >> 4) & 0b11);
      const key = toHex(request.slice(1, 1 + keyLen));
      const seq = request.slice(1 + keyLen, 1 + keyLen + seqLen);
      const known = MOCK.endpoints[key];
      state.requests.push(known ? known.path : "?" + key);
      // Unknown keys get a `WireError::UnknownKey` reply, like from the real server.
      const reply = known || MOCK.unknownKey;
      // Reply header: 8-byte key (0b11 key bits), same sequence number length.
      const header = [0b1100_0000 | (disc & 0b0011_0000), ...fromHex(reply.key), ...seq];
      const frame = cobsEncode([...header, ...fromHex(reply.body)]);
      frame.push(0);
      setTimeout(() => this.deliver(frame), (known && known.delayMs) || 1);
    }
  }

  const port = new FakePort();
  Object.defineProperty(navigator, "serial", {
    configurable: true,
    value: {
      requestPort: async () => port,
      getPorts: async () => [port],
    },
  });
})();
